INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird der Darkmode künftig die Standardeinstellung für alle neuen Webanwendungen sein?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzerpräferenzen und Kontext bestimmen die Wahl"}, {"text": "Ja", "correct": false, "because": "Darkmode ist nicht universell bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Mikrointeraktionen in Zukunft die Barrierefreiheit von Websites verschlechtern?', 2, '[{"text": "Ja", "correct": true, "because": "Unzugängliche Animationen können Nutzer ausschließen"}, {"text": "Nein", "correct": false, "because": "Verschlechterung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es wahrscheinlich, dass Darkmode künftig nur noch als optionale Funktion angeboten wird?', 2, '[{"text": "Nein", "correct": true, "because": "Seine Beliebtheit deutet auf Standardisierung hin"}, {"text": "Ja", "correct": false, "because": "Trends zeigen stärkere Integration"}]'),
('00000000-0000-0000-0000-000000000000', 'Werden Mikrointeraktionen in Zukunft ausschließlich durch KI-gesteuerte Systeme generiert?', 2, '[{"text": "Nein", "correct": true, "because": "Menschliche Gestaltung bleibt für Kreativität entscheidend"}, {"text": "Ja", "correct": false, "because": "KI wird unterstützen, nicht dominieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Darkmode künftig die Entwicklungskosten für Webseiten dauerhaft senken?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassungen und Tests erhöhen oft den Aufwand"}, {"text": "Ja", "correct": false, "because": "Kostensenkung ist nicht garantiert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher zukünftige Trend beim Darkmode wird die Nutzererfahrung am meisten beeinflussen?', 3, '[{"text": "Adaptive Farbanpassung", "correct": true, "because": "Passt sich automatisch an Umgebung an"}, {"text": "Erhöhte Farbsättigung", "correct": false, "because": "Weniger nutzerzentriert"}, {"text": "Schnellere Aktivierung", "correct": false, "because": "Technisch, nicht erlebnisorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wird künftig die größte Herausforderung bei der Integration von Mikrointeraktionen sein?', 2, '[{"text": "Gewährleistung der Barrierefreiheit", "correct": true, "because": "Inklusion wird wichtiger"}, {"text": "Reduktion der Dateigröße", "correct": false, "because": "Sekundär zur Nutzbarkeit"}, {"text": "Schnelle Implementierung", "correct": false, "because": "Qualität steht im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt des Darkmode wird in Zukunft wahrscheinlich stärker automatisiert?', 3, '[{"text": "Umschaltung basierend auf Tageszeit", "correct": true, "because": "Nutzer erwarten Kontextanpassung"}, {"text": "Manuelle Farbkonfiguration", "correct": false, "because": "Weniger praktikabel"}, {"text": "Helligkeitssteuerung der Schrift", "correct": false, "because": "Bereits Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle werden Mikrointeraktionen künftig primär in Webanwendungen übernehmen?', 2, '[{"text": "Verbesserung der Nutzerführung", "correct": true, "because": "Leiten Nutzer intuitiv"}, {"text": "Erhöhung der visuellen Komplexität", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Reduktion der Ladezeiten", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher technische Fortschritt wird den Darkmode künftig am stärksten fördern?', 3, '[{"text": "Verbesserte OLED-Technologie", "correct": true, "because": "Optimiert Energieeffizienz und Kontrast"}, {"text": "Schnellere Prozessoren", "correct": false, "because": "Weniger relevant"}, {"text": "Erhöhte Speicherkapazität", "correct": false, "because": "Kein direkter Zusammenhang"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche zukünftigen Entwicklungen könnten den Darkmode weiter etablieren?', 4, '[{"text": "Automatische Anpassung an Lichtverhältnisse", "correct": true, "because": "Verbessert Nutzerkomfort"}, {"text": "Integration mit Betriebssystemen", "correct": true, "because": "Erhöht Konsistenz"}, {"text": "Maximale Farbvielfalt", "correct": false, "because": "Kontrast ist wichtiger"}, {"text": "Personalisierte Themes", "correct": true, "because": "Erfüllt individuelle Präferenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile könnten Mikrointeraktionen in der Zukunft für Webanwendungen bieten?', 3, '[{"text": "Erhöhte Interaktivität", "correct": true, "because": "Fördert Engagement"}, {"text": "Intuitive Bedienbarkeit", "correct": true, "because": "Vereinfacht Navigation"}, {"text": "Geringerer Serveraufwand", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Gamification-Elemente", "correct": true, "because": "Macht Nutzung spielerisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen könnten künftig bei der Implementierung des Darkmode auftreten?', 4, '[{"text": "Konsistenz über Geräte hinweg", "correct": true, "because": "Unterschiedliche Displays sind komplex"}, {"text": "Einhaltung von Barrierefreiheitsstandards", "correct": true, "because": "Kontraste müssen stimmen"}, {"text": "Schnellere Ladezeiten", "correct": false, "because": "Kein direkter Zusammenhang"}, {"text": "Kompatibilität mit älteren Browsern", "correct": true, "because": "Technische Einschränkungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen könnten Mikrointeraktionen künftig in der Benutzererfahrung übernehmen?', 3, '[{"text": "Feedback bei Aktionen", "correct": true, "because": "Bestätigt Interaktionen"}, {"text": "Lenkung der Aufmerksamkeit", "correct": true, "because": "Hebt Elemente hervor"}, {"text": "Erhöhung der Dateigröße", "correct": false, "because": "Kein Ziel der Interaktionen"}, {"text": "Verbesserung der Zugänglichkeit", "correct": true, "because": "Kann inklusive Gestaltung fördern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien könnten den Einsatz von Darkmode und Mikrointeraktionen künftig unterstützen?', 3, '[{"text": "Fortschritte in CSS", "correct": true, "because": "Ermöglicht flexible Designs"}, {"text": "KI-gestützte Personalisierung", "correct": true, "because": "Passt Interaktionen an"}, {"text": "Erhöhte Serverkapazität", "correct": false, "because": "Weniger relevant"}, {"text": "Verbesserte JavaScript-Bibliotheken", "correct": true, "because": "Erleichtert Animationen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Darkmode wird künftig ausschließlich auf mobilen Geräten dominieren. b) Mikrointeraktionen können die Nutzerbindung erhöhen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Darkmode ist breiter, Interaktionen fördern Engagement"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mikrointeraktionen werden künftig die Ladezeiten von Websites signifikant verlängern. b) Der Darkmode kann die Lesbarkeit bei schlechter Umsetzung verschlechtern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Ladezeiten sind kontrollierbar, Lesbarkeit ist Risiko"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Künftig wird der Darkmode keine Anpassung an Barrierefreiheit erfordern. b) Mikrointeraktionen könnten durch Sprachsteuerung ergänzt werden.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Barrierefreiheit bleibt nötig, Sprachsteuerung ist plausibel"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Mikrointeraktionen werden künftig hauptsächlich dekorativen Zwecken dienen. b) Der Darkmode könnte durch KI personalisierter werden.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Interaktionen sind funktional, KI kann anpassen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Darkmode wird künftig keine Rolle für die Energieeffizienz spielen. b) Mikrointeraktionen könnten die Benutzerfreundlichkeit durch Feedback verbessern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Energieeffizienz bleibt relevant, Feedback hilft"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

